Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  FILE *file = NULL;
  MngInfo *mng_info = NULL;

  if (image_info == NULL || exception == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      OptionError, "InvalidArgument", "");
    return NULL;
  }

  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Entry %s", image_info->filename);

  file = fopen(image_info->filename, "rb");
  if (file == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      FileOpenError, "UnableToOpenFile", 
      image_info->filename);
    return NULL;
  }

  unsigned char signature[PNGSIG_MAX_LENGTH];
  if (fread(signature, 1, PNGSIG_LENGTH, file) != PNGSIG_LENGTH) {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), 
      CorruptImageError, "NotPNGFile", image_info->filename);
    return NULL;
  }

  if (png_sig_cmp(signature, 0, PNGSIG_LENGTH)) {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), 
      CorruptImageError, "NotPNGFile", image_info->filename);
    return NULL;
  }

  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(MngInfo));
  if (mng_info == NULL) {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), 
      ResourceLimitError, "UnableToAllocateMemory", "MngInfo");
    return NULL;
  }

  (void) memset(mng_info, 0, sizeof(MngInfo));

  if (fseek(file, 0, SEEK_SET) != 0) {
    (void) fclose(file);
    (void) RelinquishMagickMemory(mng_info);
    (void) ThrowMagickException(exception, GetMagickModule(), 
      FileOpenError, "UnableToSeekFile", image_info->filename);
    return NULL;
  }

  if (ReadPNGImageData(file, mng_info, image_info, &image, exception) != MagickPass) {
    (void) fclose(file);
    (void) RelinquishMagickMemory(mng_info);
    return NULL;
  }

  if (image->columns <= 0 || image->rows <= 0) {
    (void) fclose(file);
    (void) RelinquishMagickMemory(mng_info);
    (void) DestroyImage(image);
    (void) ThrowMagickException(exception, GetMagickModule(), 
      CorruptImageError, "InvalidImageDimensions", "");
    return NULL;
  }

  if (image->colorspace == UndefinedColorspace) {
    image->colorspace = sRGBColorspace;
  }

  (void) fclose(file);
  (void) RelinquishMagickMemory(mng_info);

  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Exit %s", image_info->filename);

  return image;
}
